import React, { useState, useEffect } from "react";
import "./VendorDashboard.css";

import {
  getProductsByVendor,
  addProduct,
  updateProduct,
  deleteProduct,
  createProduct,
  deleteProductById,
} from "../utils/api"; // Make sure your api.js has these functions

export default function VendorDashboard({ vendor }) {
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({
    id: null,
    name: "",
    description: "",
    price: "",
    stockQuantity: "",
    category: "",
    imageUrl: "",
  });
  const [editing, setEditing] = useState(false);

  // Fetch products for this vendor
  const fetchProducts = async () => {
    if (!vendor) return;
    const data = await getProductsByVendor(vendor.id);
    setProducts(data);
  };

  useEffect(() => {
    fetchProducts();
  }, [vendor]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editing) {
        await updateProduct(form.id, { ...form, vendor });
      } else {
        await createProduct({ ...form, vendor });
      }
      setForm({
        id: null,
        name: "",
        description: "",
        price: "",
        stockQuantity: "",
        category: "",
        imageUrl: "",
      });
      setEditing(false);
      fetchProducts();
    } catch (err) {
      console.error(err);
      alert("Error saving product");
    }
  };

  const handleEdit = (product) => {
    setForm(product);
    setEditing(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure?")) {
      await deleteProductById(id);
      fetchProducts();
    }
  };

  return (
    <div className="vendor-dashboard">
    <div style={{ padding: "20px" }}>
      <h2>Welcome, {vendor?.name}</h2>

      <h3>{editing ? "Edit Product" : "Add Product"}</h3>
      <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
        <input
          name="name"
          placeholder="Name"
          value={form.name}
          onChange={handleChange}
          required
        />

        <input
          name="description"
          placeholder="Description"
          value={form.description}
          onChange={handleChange}
        />
        <input
          name="price"
          placeholder="Price"
          type="number"
          step="0.01"
          value={form.price}
          onChange={handleChange}
          required
        />
        <input
          name="stockQuantity"
          placeholder="Stock Quantity"
          type="number"
          value={form.stockQuantity}
          onChange={handleChange}
          required
        />
        <input
          name="category"
          placeholder="Category"
          value={form.category}
          onChange={handleChange}
          required
        />
        <input
          name="imageUrl"
          placeholder="Image URL"
          value={form.imageUrl}
          onChange={handleChange}
        />
        <button type="submit">{editing ? "Update" : "Add"}</button>
        {editing && (
          <button
            type="button"
            onClick={() => {
              setForm({
                id: null,
                name: "",
                description: "",
                price: "",
                stockQuantity: "",
                category: "",
                imageUrl: "",
              });
              setEditing(false);
            }}
          >
            Cancel
          </button>
        )}
      </form>

      <h3>Your Products</h3>
      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>Name</th>
            <th>Price</th>
            <th>Stock</th>
            <th>Category</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {products.length === 0 && (
            <tr>
              <td colSpan="5">No products found</td>
            </tr>
          )}
          {products.map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td>{p.price}</td>
              <td>{p.stockQuantity}</td>
              <td>{p.category}</td>
              <td>
                <button onClick={() => handleEdit(p)}>Edit</button>
                <button onClick={() => handleDelete(p.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
    </div>
  );
}

